class Solution:
    def countPairs(self, coordinates: List[List[int]], k: int) -> int:
        n = len(coordinates)
        ans = 0
        for i in range(n):
            x1, y1 = coordinates[i]
            for j in range(i + 1, n):
                x2, y2 = coordinates[j]
                if (x1 ^ x2) + (y1 ^ y2) == k:
                    ans += 1
        return ans

