int countPairs(vector<vector<int>>& coordinates, int k) {
    int ans = 0, n = coordinates.size();
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)
            if ((coordinates[i][0] ^ coordinates[j][0]) +
                (coordinates[i][1] ^ coordinates[j][1]) == k) ans++;
    return ans;
}

