from collections import Counter
class Solution:
    def countPairs(self, coordinates: List[List[int]], k: int) -> int:
        cnt = Counter(map(tuple, coordinates))
        ans = 0
        for x, y in coordinates:
            for a in range(k + 1):
                tx, ty = x ^ a, y ^ (k - a)
                c = cnt.get((tx, ty), 0)
                if tx == x and ty == y:
                    c -= 1
                ans += c
        return ans // 2

