int countPairs(vector<vector<int>>& coordinates, int k) {
    map<pair<int,int>, int> cnt;
    for (auto& p : coordinates) cnt[{p[0], p[1]}]++;
    long long ans = 0;
    for (auto& p : coordinates) {
        for (int a = 0; a <= k; a++) {
            pair<int,int> t = {p[0] ^ a, p[1] ^ (k - a)};
            long long c = cnt.count(t) ? cnt[t] : 0;
            if (t.first == p[0] && t.second == p[1]) c--;
            ans += c;
        }
    }
    return ans / 2;
}

