public int countPairs(int[][] coordinates, int k) {
    Map<Long, Integer> cnt = new HashMap<>();
    for (int[] p : coordinates) cnt.merge(((long) p[0] << 32) | p[1], 1, Integer::sum);
    long ans = 0;
    for (int[] p : coordinates) {
        for (int a = 0; a <= k; a++) {
            long key = (((long) (p[0] ^ a)) << 32) | (p[1] ^ (k - a));
            int c = cnt.getOrDefault(key, 0);
            if (a == 0 && k == 0) c--;
            ans += c;
        }
    }
    return (int) (ans / 2);
}

